def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        grid[x][y] = value

    # Initialize the DP table
    dp = [[0] * N for _ in range(N)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j] = grid[i][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # The maximum value on the two paths is the maximum value in the bottom-right corner of the DP table
    return dp[N-1][N-1]

