    result = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if i == n:
            term = f"{abs(coeff)}x^{n}"
        elif i == 1:
            term = f"{abs(coeff)}x"
        else:
            term = f"{abs(coeff)}x^{i}"
        if coeff > 0:
            result.append(term)
        else:
            result.append(f"-{term}")
    return " + ".join(result)

